<script lang="ts">
  import { onMount } from 'svelte';
  let planned = $state(1000); let trials = $state(0); let outside = $state(0); let alpha = $state(.05); let category = $state(0); let latestGlobal = $state<any>(null);
  onMount(() => { try { const saved=JSON.parse(localStorage.getItem('muvs-statistika-config')||'{}'); planned=Number(saved.batches)||1000; alpha=1-(Number(saved.confidence)||.95); } catch {} const receive=(event:Event)=>{const d=(event as CustomEvent).detail;if(d?.global){latestGlobal=d.global;trials=d.global.samples;outside=d.global.categories?.[category]?.outside??0}};const categoryChange=(event:Event)=>{category=Number((event as CustomEvent).detail?.index??0);outside=latestGlobal?.categories?.[category]?.outside??0};window.addEventListener('muvs-simulation-update',receive);window.addEventListener('muvs-category-change',categoryChange);return()=>{window.removeEventListener('muvs-simulation-update',receive);window.removeEventListener('muvs-category-change',categoryChange)}});
  const effectiveTrials=$derived(Math.max(1,planned)); const mean=$derived(effectiveTrials*alpha); const sd=$derived(Math.sqrt(Math.max(0,effectiveTrials*alpha*(1-alpha)))); const low=$derived(Math.max(0,Math.floor(mean-1.96*sd))); const high=$derived(Math.ceil(mean+1.96*sd)); const lo=$derived(Math.max(0,Math.floor(mean-4*sd))); const hi=$derived(Math.max(1,Math.ceil(mean+4*sd))); const points=$derived(Array.from({length:Math.max(2,hi-lo+1)},(_,i)=>{const k=lo+i;return{k,p:binomialPmf(effectiveTrials,k,alpha)}})); const maxP=$derived(Math.max(.001,...points.map(p=>p.p)));
  function binomialPmf(n:number,k:number,p:number){if(k<0||k>n)return 0;let log=0;for(let i=1;i<=k;i++)log+=Math.log(n-k+i)-Math.log(i);return Math.exp(log+k*Math.log(p)+(n-k)*Math.log(1-p))}
  const x=(k:number)=>40+(k-lo)/(hi-lo||1)*520,y=(p:number)=>170-p/maxP*135;
</script>
{#if planned>0}<section class="binomial-card"><div class="binomial-head"><div><div class="card-kicker">NÁHODNÉ KOLÍSÁNÍ CHYB</div><h3>Binomické rozdělení počtu chybných intervalů</h3><p>Šedá silueta je předpoklad pro {planned.toLocaleString('cs-CZ')} opakování. Zeleně se průběžně vyplňuje skutečný výsledek simulace.</p></div><div class="binomial-stats"><strong>{outside}</strong><span>skutečně</span></div></div><svg viewBox="0 0 600 230" role="img" aria-label={`Binomické rozdělení pro ${planned} opakování`}><title>Binomické rozdělení počtu chybných intervalů</title><line x1="40" x2="560" y1="170" y2="170" stroke="#9bc4b0"/><rect x={x(low)} y="20" width={Math.max(2,x(high)-x(low))} height="150" fill="#cfe6bd44" stroke="#6b965d" stroke-dasharray="5 4"/><line x1={x(low)} x2={x(low)} y1="25" y2="180" stroke="#d75d45" stroke-dasharray="4 3"/><line x1={x(high)} x2={x(high)} y1="25" y2="180" stroke="#d75d45" stroke-dasharray="4 3"/><text x={x(low)} y="18" text-anchor="middle">dolní hranice</text><text x={x(high)} y="18" text-anchor="middle">horní hranice</text>{#each points as point}<rect x={x(point.k)-3} y={y(point.p)} width="6" height={170-y(point.p)} fill={point.k<low||point.k>high?'#d86b58':point.k<=outside&&trials>0?'#5a9b78':'#a9bcb1'} rx="2"><title>{point.k} chybných intervalů: {(point.p*100).toFixed(2)} %</title></rect>{/each}<line x1={x(mean)} x2={x(mean)} y1="20" y2="175" stroke="#f1c69a" stroke-dasharray="5 4"/><line x1={x(outside)} x2={x(outside)} y1="15" y2="180" stroke="#d75d45" stroke-width="2"/><text x={x(mean)} y="198" text-anchor="middle">očekáváno {mean.toFixed(1)}</text><text x={x(outside)} y="215" text-anchor="middle">skutečně {outside}</text><text x="40" y="215">počet chybných intervalů</text><text x="560" y="215" text-anchor="end">zelená = průběh simulace · červené = ocasní oblasti α</text></svg><p class="binomial-note">Červené konce jsou přibližně nejméně pravděpodobné hodnoty (dohromady asi α). Nejde o zákaz — občas se mohou objevit.</p></section>{/if}
